function draw({svg,width,height,progress,params}) {
  const ns='http://www.w3.org/2000/svg';
  svg.replaceChildren(); svg.setAttribute('viewBox',`0 0 ${width} ${height}`);
  const C={ink:'#263b45',muted:'#66777b',line:'#d8dfde',cpu:'#498e9a',gpu:'#b27947',wait:'#e8ecea',paper:'#fafbf8'};
  const el=(tag,a={},s)=>{const e=document.createElementNS(ns,tag); for(const [k,v] of Object.entries(a))e.setAttribute(k,v);if(s!==undefined)e.textContent=s;svg.appendChild(e);return e;};
  const txt=(x,y,s,a={})=>el('text',{x,y,fill:C.ink,'font-size':14,'font-family':'system-ui, sans-serif',...a},s);
  const line=(x1,y1,x2,y2,a={})=>el('line',{x1,y1,x2,y2,stroke:C.line,'stroke-width':1,...a});
  const box=(x,y,w,h,fill,a={})=>el('rect',{x,y,width:Math.max(0,w),height:h,rx:3,fill,...a});
  const m=width<520,L=m?26:104,R=width-24;
  const d=Number(params.gpuTime),end=1+3*d,now=progress*end,X=t=>L+t/end*(R-L);
  const cy=m?112:96,gy=m?224:184,bh=28,axis=m?278:238;
  el('title',{},'提交计时与同步计时：三次提交，一条 GPU 队列');
  box(0,0,width,height,C.paper);
  txt(L,29,`观察时刻 ${now.toFixed(1)}`,{'font-size':16,'font-weight':600});
  txt(R,29,'示例时间',{'text-anchor':'end',fill:C.muted,'font-size':13});
  if(m){txt(L,cy-25,'Python · 提交');txt(L,gy-25,'GPU · 执行');}
  else{txt(12,cy+18,'Python');txt(12,gy+18,'GPU');}
  box(X(3),cy,R-X(3),bh,C.wait);
  const waitRun=Math.max(0,Math.min(now,end)-3);
  if(waitRun>0)box(X(3),cy,X(3+waitRun)-X(3),bh,'#d1dbd7');
  txt((X(3)+R)/2,cy+19,'同步等待',{'text-anchor':'middle',fill:C.muted,'font-size':13});
  const starts=[];
  for(let i=0;i<3;i++){
    const s=1+i*d;starts.push(s);
    box(X(i),cy,X(i+1)-X(i)-2,bh,C.cpu,{opacity:0.17});
    const pc=Math.max(0,Math.min(1,now-i));
    if(pc>0)box(X(i),cy,Math.max(0,X(i+pc)-X(i)-2),bh,C.cpu);
    txt((X(i)+X(i+1))/2,cy-7,String(i+1),{'text-anchor':'middle','font-size':13,fill:C.muted});
    box(X(s),gy,X(s+d)-X(s)-2,bh,C.gpu,{opacity:0.17});
    const pg=Math.max(0,Math.min(d,now-s));
    if(pg>0)box(X(s),gy,Math.max(0,X(s+pg)-X(s)-2),bh,C.gpu);
    txt((X(s)+X(s+d))/2,gy+19,`任务 ${i+1}`,{'text-anchor':'middle','font-size':13});
  }
  line(X(3),cy-39,X(3),cy+bh+8,{stroke:C.cpu,'stroke-dasharray':'3 4'});
  txt(X(3),cy-44,'提交完',{'text-anchor':'middle',fill:C.cpu,'font-size':13});
  line(R,gy-49,R,gy+bh+8,{stroke:C.gpu,'stroke-dasharray':'3 4'});
  txt(R,gy-55,'计算完',{'text-anchor':'end',fill:C.gpu,'font-size':13});
  line(L,axis,R,axis);
  for(const t of [0,3,end]){line(X(t),axis-4,X(t),axis+4);txt(X(t),axis+22,String(t),{'text-anchor':t===end?'end':'middle','font-size':13,fill:C.muted});}
  line(X(now),cy-12,X(now),gy+bh+9,{stroke:'#39515a','stroke-width':1.5});
  el('circle',{cx:X(now),cy:cy-14,r:3.5,fill:C.ink});
  const by=m?335:285;
  txt(L,by,'未同步计时',{'font-size':13,fill:C.muted});
  txt(L+91,by,'3',{'font-size':18,'font-weight':600,fill:C.cpu});
  if(m){txt(L,by+32,'同步后计时',{'font-size':13,fill:C.muted});txt(L+91,by+32,end.toFixed(1),{'font-size':18,'font-weight':600,fill:C.gpu});txt(R,by+32,`多等 ${end-3}`,{'text-anchor':'end',fill:C.muted,'font-size':13});}
  else{txt(width/2,by,'同步后计时',{'font-size':13,fill:C.muted});txt(width/2+91,by,end.toFixed(1),{'font-size':18,'font-weight':600,fill:C.gpu});txt(R,by,`多等 ${end-3}`,{'text-anchor':'end',fill:C.muted,'font-size':13});}
  return {enqueueDuration:1,gpuDuration:d,taskCount:3,gpuStarts:starts,enqueueEnd:3,completion:end,synchronizationWait:end-3,observedTime:now,completedTasks:starts.filter(s=>now>=s+d).length};
}

function draw({svg,width,height,params}) {
  const ns='http://www.w3.org/2000/svg';svg.replaceChildren();svg.setAttribute('viewBox',`0 0 ${width} ${height}`);
  const C={ink:'#263b45',muted:'#66777b',line:'#d8dfde',cpu:'#498e9a',gpu:'#b27947',ret:'#6b747c',paper:'#fafbf8'};
  const el=(tag,a={},s)=>{const e=document.createElementNS(ns,tag);for(const[k,v]of Object.entries(a))e.setAttribute(k,v);if(s!==undefined)e.textContent=s;svg.appendChild(e);return e;};
  const txt=(x,y,s,a={})=>el('text',{x,y,fill:C.ink,'font-size':14,'font-family':'system-ui, sans-serif',...a},s);
  const line=(x1,y1,x2,y2,a={})=>el('line',{x1,y1,x2,y2,stroke:C.line,'stroke-width':1,...a});
  const box=(x,y,w,h,fill,a={})=>el('rect',{x,y,width:Math.max(0,w),height:h,fill,rx:2,...a});
  const a=Number(params.t1),b=Number(params.t2),c=1,N=4;
  const starts=[],ends=[];let previous=0;
  for(let i=0;i<N;i++){const s=Math.max((i+1)*a,previous);starts.push(s);previous=s+b;ends.push(previous);}
  const sync=N*(a+b+c),async=previous+c,L=26,R=width-26,X=t=>L+t/sync*(R-L),m=width<520;
  const sy=82,cy=m?177:173,gy=m?262:253,axis=m?312:301;
  el('title',{},'四个独立任务的逐次等待与流水线调度');
  box(0,0,width,height,C.paper);
  const legend=[['提交 t₁',C.cpu],['计算 t₂',C.gpu],['返回 1',C.ret]];
  legend.forEach(([s,c],i)=>{const x=L+i*(m?96:145);box(x,16,10,10,c);txt(x+16,26,s,{'font-size':13});});
  txt(L,sy-15,'逐次等待');txt(R,sy-15,`总时长 ${sync.toFixed(1)}`,{'text-anchor':'end','font-size':13,fill:C.muted});
  for(let i=0;i<N;i++){
    const s=i*(a+b+c);
    box(X(s),sy,X(s+a)-X(s),26,C.cpu);
    box(X(s+a),sy,X(s+a+b)-X(s+a),26,C.gpu);
    box(X(s+a+b),sy,X(s+a+b+c)-X(s+a+b),26,C.ret);
    txt(X(s+(a+b+c)/2),sy+45,String(i+1),{'text-anchor':'middle','font-size':13,fill:C.muted});
    if(i>0)line(X(s),sy,X(s),sy+26,{stroke:C.paper,'stroke-width':2});
  }
  txt(L,cy-16,'异步 · 四次提交');
  txt(R,cy-16,`提交完 ${N*a}`,{'text-anchor':'end','font-size':13,fill:C.muted});
  box(L,cy,X(N*a)-L,26,C.cpu,{opacity:0.15});
  for(let i=0;i<N;i++){
    box(X(i*a),cy,Math.max(0,X((i+1)*a)-X(i*a)-1),26,C.cpu);
  }
  txt(L,gy-16,'异步 · 后端');txt(R,gy-16,`总时长 ${async.toFixed(1)}`,{'text-anchor':'end','font-size':13,fill:C.muted});
  for(let i=0;i<N;i++){
    line(X((i+1)*a),cy+27,X(starts[i]),gy-4,{stroke:C.cpu,'stroke-dasharray':'2 4',opacity:0.5});
    box(X(starts[i]),gy,Math.max(0,X(ends[i])-X(starts[i])-1),26,C.gpu);
    if(starts[i]>(i===0?0:ends[i-1]))line(X(i===0?0:ends[i-1]),gy+13,X(starts[i]),gy+13,{stroke:C.line,'stroke-width':3});
  }
  box(X(previous),gy,X(async)-X(previous),26,C.ret);
  line(X(async),gy+27,X(async),axis-6,{stroke:C.ret,'stroke-dasharray':'3 3'});
  line(L,axis,R,axis);
  [0,sync/4,sync/2,3*sync/4,sync].forEach(t=>{line(X(t),axis-4,X(t),axis+4);txt(X(t),axis+21,String(t),{'text-anchor':'middle','font-size':13,fill:C.muted});});
  txt(R,axis+43,'时间 / 示例单位',{'text-anchor':'end','font-size':13,fill:C.muted});
  const note=a<=b?'后端较慢 · T = t₁ + 4t₂ + 1':'前端较慢 · T = 4t₁ + t₂ + 1';
  txt(L,height-15,note,{'font-size':14,fill:C.ink});
  return {taskCount:N,t1:a,t2:b,t3:c,enqueueEnds:Array.from({length:N},(_,i)=>(i+1)*a),backendStarts:starts,backendEnds:ends,synchronous:sync,asynchronous:async,exactFormula:a+b+(N-1)*Math.max(a,b)+c,backendIdle:starts.reduce((v,s,i)=>v+Math.max(0,s-(i?ends[i-1]:0)),0),bottleneck:a>b?'front':'back'};
}
